#pragma once
// Bouncing Ball - gravity ball, return it with the paddle (stick left/right). Every 5 returns: higher gravity = faster ball,
// narrower paddle. Hit with the paddle edge to steer the ball. Miss = game over.
#define BB_ID 11
static float bbX, bbY, bbVx, bbVy, bbG, bbPx; static uint8_t bbLvl, bbTr[5][2]; static uint16_t bbScore, bbHi;
static bool bbOver; static uint32_t bbServe; static uint8_t bbFlash;
static int bbPw() { int w = 24 - 2 * (bbLvl - 1); return w < 12 ? 12 : w; }
static void bbInit() {
  bbPx = 54; bbLvl = 1; bbG = 0.20f; bbScore = 0; bbOver = false; bbHi = hiGet(BB_ID); bbFlash = 0;
  bbX = 20 + random(88); bbY = 12; bbVx = random(2) ? 0.8f : -0.8f; bbVy = 0; bbServe = millis() + 600;
  for (uint8_t i = 0; i < 5; i++) { bbTr[i][0] = bbX; bbTr[i][1] = bbY; }
}
static void bbUpdate() {
  if (bbOver) { if (overKeys()) bbInit(); return; }
  int pw = bbPw(); bbPx += in.ax * 0.07f; if (bbPx < 0) bbPx = 0; if (bbPx > 128 - pw) bbPx = 128 - pw;
  if (bbFlash) bbFlash--;
  if ((int32_t)(millis() - bbServe) < 0) return;
  for (uint8_t i = 4; i > 0; i--) { bbTr[i][0] = bbTr[i - 1][0]; bbTr[i][1] = bbTr[i - 1][1]; }
  bbTr[0][0] = (uint8_t)bbX; bbTr[0][1] = (uint8_t)bbY;
  bbVy += bbG; bbX += bbVx; bbY += bbVy;
  if (bbX < 2) { bbX = 2; bbVx = -bbVx; sfx(SFX_MOVE); } if (bbX > 125) { bbX = 125; bbVx = -bbVx; sfx(SFX_MOVE); }
  if (bbY < 11) { bbY = 11; bbVy = -bbVy * 0.8f; sfx(SFX_MOVE); }
  if (bbVy > 0 && bbY >= 56 && bbY - bbVy <= 60 && bbX + 2 >= bbPx && bbX - 2 <= bbPx + pw) {   // paddle return
    float off = (bbX - (bbPx + pw / 2.0f)) / (pw / 2.0f + 2);                                // -1..1
    bbY = 56; bbVy = -sqrtf(2 * bbG * 46.0f);                                               // peak ~46 px, any gravity
    bbVx = off * (2.2f + 0.12f * bbLvl) + in.ax * 0.012f; if (bbVx > 4) bbVx = 4; if (bbVx < -4) bbVx = -4;
    bbScore++; bbFlash = 4; uint8_t nl = 1 + bbScore / 5;
    if (nl > bbLvl) { bbLvl = nl; bbG += 0.025f; if (bbG > 0.6f) bbG = 0.6f; bannerLevel(nl); fx(SFX_LEVEL, C_CYAN, 200); }
    else fx(SFX_COIN, C_GOOD, 90);
  }
  if (bbY > 66) { bbOver = true; endRun(BB_ID, bbScore, bbHi); }
}
static void bbDraw() {
  char b[32]; u8g2.setFont(FONT_S); snprintf(b, sizeof b, "SCORE %u  LV%u  HI %u", bbScore, bbLvl, bbHi); textC(b, 7);
  u8g2.drawHLine(0, 9, 128);
  for (uint8_t i = 4; i < 5; i++) u8g2.drawPixel(bbTr[i][0], bbTr[i][1]);                  // short trail
  u8g2.drawPixel(bbTr[2][0], bbTr[2][1]); u8g2.drawPixel(bbTr[0][0], bbTr[0][1]);
  u8g2.drawDisc((int)bbX, (int)bbY, 2);
  if (bbFlash) u8g2.drawFrame((int)bbPx - bbFlash, 58 - bbFlash, bbPw() + 2 * bbFlash, 3 + 2 * bbFlash);
  u8g2.drawBox((int)bbPx, 59, bbPw(), 3);
  if (bbOver) overBox(bbScore, bbHi);
}
static void bbIcon(int x, int y) {
  for (int i = 0; i < 6; i++) u8g2.drawPixel(x + 6 + i * 3, y + 24 - (i * (9 - i)) / 2 - 4);   // arc
  u8g2.drawDisc(x + 22, y + 10, 3); u8g2.drawBox(x + 6, y + 28, 20, 3);
}

#pragma once
// Breakout - 5 brick layouts that repeat harder. Stick L/R = paddle, A (or up) = launch. W = wide paddle, L = extra life.
#define BO_ID 6
#define BO_C  8
#define BO_R  5
static uint8_t boBr[BO_R][BO_C];
static float boBx, boBy, boVx, boVy, boPx;
static uint8_t boLives, boLvl, boLeft; static uint16_t boScore, boHi, boWide; static bool boLaunched, boOver;
struct BoC { float x, y; uint8_t t; bool on; };
static BoC boC[3];
static int boPw() { return boWide ? 32 : 20; }

static void boLoad(uint8_t lv) {
  boLeft = 0; uint8_t p = (lv - 1) % 5;
  for (uint8_t r = 0; r < BO_R; r++) for (uint8_t c = 0; c < BO_C; c++) {
    uint8_t h = 0;
    switch (p) {
      case 0: h = (r < 4) ? 1 : 0; break;
      case 1: h = ((r + c) & 1) ? 1 : 0; break;
      case 2: h = (r < 4 && c >= r && c < BO_C - r) ? 1 : 0; break;
      case 3: h = (c & 1) ? 0 : ((r < 2) ? 2 : 1); break;
      default: h = (r < 2) ? 2 : 1;
    }
    if (lv > 5 && h == 1 && ((r + c) % 3 == 0)) h = 2;
    boBr[r][c] = h; if (h) boLeft++;
  }
  for (uint8_t i = 0; i < 3; i++) boC[i].on = false;
  boLaunched = false;
}
static void boInit() {
  boLvl = 1; boLives = 3; boScore = 0; boWide = 0; boOver = false; boPx = 54; boHi = hiGet(BO_ID); boLoad(1);
}
static bool boBrick() {
  int cx = (int)(boBx + 1), cy = (int)(boBy + 1);
  if (cy < 10) return false;
  int row = (cy - 10) / 6, col = cx / 16;
  if (row >= BO_R || col < 0 || col >= BO_C) return false;
  uint8_t &h = boBr[row][col]; if (!h) return false;
  h--;
  if (h == 0) {
    boLeft--; boScore += 10; fx(SFX_COIN, C_ORANGE, 60);
    if (random(100) < 12) for (uint8_t i = 0; i < 3; i++) if (!boC[i].on) { boC[i] = {(float)(col * 16 + 5), (float)(10 + row * 6), (uint8_t)random(2), true}; break; }
  } else { boScore += 2; sfx(SFX_MOVE); }
  if (boLeft == 0) { boLvl++; bannerLevel(boLvl); fx(SFX_LEVEL, C_GOOD, 300); boLoad(boLvl); }
  return true;
}
static void boUpdate() {
  if (boOver) { if (overKeys()) boInit(); return; }
  if (boWide) boWide--;
  boPx += in.ax * 0.045f; int pw = boPw(); if (boPx < 0) boPx = 0; if (boPx > 128 - pw) boPx = 128 - pw;
  for (uint8_t i = 0; i < 3; i++) {
    if (!boC[i].on) continue;
    boC[i].y += 1.0f; if (boC[i].y > 64) { boC[i].on = false; continue; }
    if (hitBox(boC[i].x, boC[i].y, 6, 5, boPx, 60, pw, 3)) {
      boC[i].on = false;
      if (boC[i].t == 0) boWide = 600; else if (boLives < 5) boLives++;
      fx(SFX_POWER, C_GOOD, 150);
    }
  }
  if (!boLaunched) {
    boBx = boPx + pw / 2 - 1; boBy = 57;
    if (in.aP || in.py < 0) {
      boLaunched = true; boVx = random(2) ? 1.2f : -1.2f;
      float s = 1.8f + 0.15f * boLvl; if (s > 3.2f) s = 3.2f; boVy = -s; sfx(SFX_JUMP);
    }
    return;
  }
  boBx += boVx;
  if (boBx < 0) { boBx = 0; boVx = -boVx; } if (boBx > 126) { boBx = 126; boVx = -boVx; }
  if (boBrick()) boVx = -boVx;
  boBy += boVy; if (boBy < 8) { boBy = 8; boVy = -boVy; }
  if (boBrick()) boVy = -boVy;
  if (boLaunched && boVy > 0 && boBy + 2 >= 60 && boBy <= 62 && boBx + 2 >= boPx && boBx <= boPx + pw) {
    float sp = fabsf(boVy) * 1.03f; if (sp > 3.4f) sp = 3.4f;
    boVy = -sp; boBy = 57.5f; boVx = ((boBx + 1) - (boPx + pw / 2.0f)) / (pw / 2.0f) * 2.4f; sfx(SFX_SELECT);
  }
  if (boBy > 64) {
    boLives--; fx(SFX_HIT, C_BAD, 250); boLaunched = false;
    if (boLives == 0) { boOver = true; endRun(BO_ID, boScore, boHi); }
  }
}
static void boDraw() {
  char b[28]; u8g2.setFont(FONT_S);
  snprintf(b, sizeof b, "L%u LV%u %u HI %u", boLives, boLvl, boScore, boHi); u8g2.drawStr(1, 7, b);
  for (uint8_t r = 0; r < BO_R; r++) for (uint8_t c = 0; c < BO_C; c++) if (boBr[r][c]) {
    u8g2.drawBox(c * 16 + 1, 10 + r * 6, 14, 4);
    if (boBr[r][c] == 1 && boLvl >= 1) { u8g2.setDrawColor(0); u8g2.drawHLine(c * 16 + 3, 11 + r * 6, 10); u8g2.setDrawColor(1); }
  }
  for (uint8_t i = 0; i < 3; i++) if (boC[i].on) { u8g2.drawFrame((int)boC[i].x, (int)boC[i].y, 7, 6); u8g2.drawPixel((int)boC[i].x + 3, (int)boC[i].y + 2); u8g2.drawPixel((int)boC[i].x + (boC[i].t ? 2 : 4), (int)boC[i].y + 3); }
  u8g2.drawBox((int)boPx, 60, boPw(), 3); u8g2.drawBox((int)boBx, (int)boBy, 2, 2);
  if (!boLaunched && !boOver) { u8g2.setFont(FONT_S); textC("A: launch", 52); }
  if (boOver) overBox(boScore, boHi);
}
static void boIcon(int x, int y) {
  for (int r = 0; r < 3; r++) for (int c = 0; c < 4; c++) u8g2.drawBox(x + c * 8, y + 3 + r * 5, 7, 3);
  u8g2.drawBox(x + 8, y + 27, 14, 3); u8g2.drawBox(x + 20, y + 19, 2, 2);
}

#pragma once
// Cave Copter - hold A (or stick up) to climb, release to sink. Caves narrow, pillars appear, speed grows.
#define CP_ID 4
static uint8_t cT[128], cB[128], cM[128], cH[128];
static float cY, cVy, cAcc, cDist, cTr[6];
static int cCen, cDir, cGap; static uint8_t cPil, cLevel, cFr; static uint16_t cScore, cHi; static bool cDead;

static void cpPush() {
  if (random(100) < 12) cDir = random(3) - 1;
  cCen += cDir * (1 + (random(3) == 0));
  int lo = 10 + cGap / 2, hi = 62 - cGap / 2;
  if (cCen < lo) { cCen = lo; cDir = 1; } if (cCen > hi) { cCen = hi; cDir = -1; }
  if (cPil == 0 && cLevel >= 2 && random(100) < 2) cPil = 7;
  memmove(cT, cT + 1, 127); memmove(cB, cB + 1, 127); memmove(cM, cM + 1, 127); memmove(cH, cH + 1, 127);
  cT[127] = cCen - cGap / 2; cB[127] = cCen + cGap / 2;
  if (cPil) { cM[127] = cCen - cGap / 8; cH[127] = cGap / 4; cPil--; } else cH[127] = 0;
}
static void cpInit() {
  cY = 32; cVy = 0; cAcc = 0; cDist = 0; cCen = 36; cDir = 0; cGap = 44; cPil = 0; cLevel = 1; cScore = 0; cDead = false; cFr = 0;
  cHi = hiGet(CP_ID); for (uint8_t i = 0; i < 6; i++) cTr[i] = 32;
  for (uint8_t i = 0; i < 128; i++) cpPush();
}
static void cpUpdate() {
  if (cDead) { if (overKeys()) cpInit(); return; }
  bool up = in.a || in.dy < 0;
  cVy += up ? -0.5f : 0.32f; if (cVy > 3) cVy = 3; if (cVy < -3) cVy = -3; cY += cVy;
  float spd = 1.0f + cLevel * 0.2f; if (spd > 3.0f) spd = 3.0f;
  cAcc += spd; cDist += spd;
  while (cAcc >= 1) { cAcc -= 1; cpPush(); }
  cScore = (uint16_t)(cDist / 8);
  uint8_t nl = 1 + cScore / 60;
  if (nl > cLevel) { cLevel = nl; cGap = imax(26, 44 - cLevel * 2); bannerLevel(nl); fx(SFX_LEVEL, C_CYAN, 200); }
  cFr++; for (uint8_t i = 5; i > 0; i--) cTr[i] = cTr[i - 1]; cTr[0] = cY;
  bool hit = false;
  for (uint8_t x = 24; x < 32; x++) {
    if (cY < cT[x] || cY + 5 >= cB[x]) hit = true;
    if (cH[x] && cY + 5 > cM[x] && cY < cM[x] + cH[x]) hit = true;
  }
  if (hit) { cDead = true; endRun(CP_ID, cScore, cHi); }
}
static void cpDraw() {
  for (uint8_t i = 0; i < 128; i++) {
    if (cT[i] > 8) u8g2.drawVLine(i, 8, cT[i] - 8);
    if (cB[i] < 64) u8g2.drawVLine(i, cB[i], 64 - cB[i]);
    if (cH[i]) u8g2.drawVLine(i, cM[i], cH[i]);
  }
  for (uint8_t i = 1; i < 6; i += 2) u8g2.drawPixel(22 - i * 3, (int)cTr[i] + 3);
  int y = (int)cY;
  u8g2.drawBox(24, y + 1, 7, 4); u8g2.drawBox(20, y + 2, 4, 1); u8g2.drawVLine(19, y, 3);
  u8g2.drawHLine(24 + ((cFr & 2) ? 0 : 1), y, (cFr & 2) ? 9 : 7); u8g2.drawHLine(24, y + 5, 7);
  u8g2.setDrawColor(0); u8g2.drawPixel(28, y + 2); u8g2.setDrawColor(1);
  char b[28]; u8g2.setFont(FONT_S);
  snprintf(b, sizeof b, "DIST %u LV%u  HI %u", cScore, cLevel, cHi); u8g2.setDrawColor(0); u8g2.drawBox(0, 0, 128, 8); u8g2.setDrawColor(1); u8g2.drawStr(1, 7, b);
  if (cDead) overBox(cScore, cHi);
}
static void cpIcon(int x, int y) {
  u8g2.drawBox(x, y, 32, 5); u8g2.drawBox(x, y + 27, 32, 5); u8g2.drawBox(x + 20, y + 5, 4, 5);
  u8g2.drawBox(x + 6, y + 14, 9, 5); u8g2.drawBox(x + 2, y + 15, 4, 1); u8g2.drawHLine(x + 5, y + 13, 11); u8g2.drawHLine(x + 6, y + 19, 8);
}

#pragma once
// Cricket - batting chase. Bowler runs in and bowls; press A (drive) or B (loft) as the ball reaches the bat.
// Stick aims the shot: match the ball's line (off / straight / leg). Timing + line + loft decide 0,1,2,3,4,6 or a wicket.
// 2 overs, 3 wickets, beat the target to win. Score = runs.
#define CR_ID    10
#define CR_BALLS 12
#define CR_WKTS  3
#define CR_HITY  47      // ball y where the bat meets it
#define CR_STMY  55      // ball y where it reaches the stumps
enum : uint8_t { CRS_RUN, CRS_BALL, CRS_FLY, CRS_RES, CRS_OVER };
static const int8_t crFld[6][2] = {{46,20},{82,20},{40,36},{88,36},{47,54},{81,54}};
static uint8_t crSt, crBalls, crWk, crKind, crOutK, crSN; static uint16_t crRuns, crHi, crT, crTgt;
static int8_t crLine, crSx, crSwDir, crSwF; static bool crSwung, crLoft, crWin; static char crStrip[7];
static float crBy, crSp, crFx, crFy, crVx, crVy; static uint8_t crFl, crFmax; static int8_t crPend;   // crPend: runs from the shot (-1 = wicket)

static void crDeliver() {
  crSt = CRS_RUN; crT = 0; crSwF = -1; crSwung = false; crLine = random(-1, 2); crSx = random(-3, 4);
  crKind = random(3); crSp = crKind == 0 ? 1.0f : (crKind == 1 ? 1.5f : 2.2f); crBy = 17; crOutK = 0;
}
static void crInit() {
  crRuns = 0; crBalls = 0; crWk = 0; crSN = 0; crWin = false; crHi = hiGet(CR_ID); crTgt = 20 + random(0, 13);
  memset(crStrip, 0, sizeof crStrip); crDeliver();
}
static void crRecord(char c) { if (crSN >= 6) { crSN = 0; memset(crStrip, 0, sizeof crStrip); } crStrip[crSN++] = c; }
static void crResolve(int8_t runs, uint8_t outKind, const char* msg) {   // runs<0 = no scoring ball; outKind 1 caught 2 bowled
  crBalls++; char c = '.';
  if (outKind) { crWk++; c = 'W'; fx(SFX_HIT, C_BAD, 300); }
  else if (runs >= 6) { c = '6'; fx(SFX_LEVEL, C_GOLD, 300); }
  else if (runs == 4) { c = '4'; fx(SFX_LINE, C_CYAN, 200); }
  else if (runs > 0) { c = '0' + runs; fx(SFX_COIN, C_GOOD, 100); }
  else sfx(SFX_MOVE);
  if (runs > 0) crRuns += runs;
  crRecord(c); banner(msg); crSt = CRS_RES; crT = 0; crOutK = outKind;
  if (crRuns >= crTgt) crWin = true;
}
static void crHitBall(uint8_t s, bool loft) {   // s: 0 perfect .. 3 edge. Outcome table, a bit of luck for variety
  uint8_t r = random(10); int8_t runs = 0; bool out = false;
  if (!loft) switch (s) {
    case 0: runs = r < 6 ? 4 : (r < 8 ? 3 : 2); break;
    case 1: runs = r < 5 ? 2 : (r < 8 ? 1 : 3); break;
    case 2: runs = r < 3 ? 0 : 1; break;
    default: if (r < 3) out = true; else runs = 1;
  } else switch (s) {
    case 0: runs = r < 7 ? 6 : 4; break;
    case 1: if (r < 4) runs = 6; else if (r < 8) runs = 4; else out = true; break;
    case 2: if (r < 5) out = true; else runs = 2; break;
    default: if (r < 7) out = true; else runs = 4;
  }
  crPend = out ? -1 : runs; crSt = CRS_FLY; crFx = 64; crFy = CR_HITY; crFl = 0; crOutK = out ? 1 : 0;
  if (out) {   // fly to a fielder on the chosen side (straight = back to the bowler)
    int tx = crSwDir < 0 ? 40 : (crSwDir > 0 ? 88 : 64), ty = crSwDir ? 36 : 16; crFmax = 14;
    crVx = (tx - 64) / 14.0f; crVy = (ty - CR_HITY) / 14.0f;
  } else {
    crVx = crSwDir * 2.0f; crVy = crSwDir ? -1.2f : -2.4f; crFmax = runs >= 4 ? 40 : 6 + 3 * runs;
    if (runs == 0) crFmax = 4;
  }
  fx(SFX_JUMP, C_WHITE, 60);
}
static void crSwing() {   // A = drive, B = loft; evaluated at the moment of the press
  crSwung = true; crSwF = 0; crLoft = in.bP; crSwDir = in.dx;
  float t = (crBy - CR_HITY) / crSp; if (t < 0) t = -t;     // timing error in frames
  if (t > 5.0f) { sfx(SFX_DUCK); return; }                   // whiff: ball carries on
  uint8_t s = t <= 1.6f ? 0 : (t <= 3.2f ? 1 : 2);
  int d = crSwDir - crLine; if (d < 0) d = -d; s += d; if (s > 3) s = 3;   // playing across the line costs quality
  crHitBall(s, crLoft);
}
static void crUpdate() {
  if (crSt == CRS_OVER) { if (overKeys()) crInit(); return; }
  crT++;
  if (crSwF >= 0 && crSwF < 8) { if (crT & 1) crSwF++; }
  switch (crSt) {
    case CRS_RUN: if (crT >= 24) { crSt = CRS_BALL; crT = 0; sfx(SFX_DUCK); } break;
    case CRS_BALL:
      crBy += crSp;
      if (!crSwung && (in.aP || in.bP)) crSwing();
      if (crSt == CRS_BALL && crBy >= CR_STMY) {
        if (crLine == 0) crResolve(0, 2, "BOWLED!"); else crResolve(0, 0, "DOT BALL");
      }
      break;
    case CRS_FLY: {
      crFx += crVx; crFy += crVy; crFl++;
      int dx = (int)crFx - 64, dy = (int)crFy - 36; bool rope = dx * dx + dy * dy >= 28 * 28;
      bool done = crFl >= crFmax || (crPend >= 4 && rope);
      if (done) {
        if (crPend < 0) crResolve(0, 1, "CAUGHT!");
        else if (crPend == 0) crResolve(0, 0, "DOT BALL");
        else if (crPend == 4) crResolve(4, 0, "FOUR!");
        else if (crPend == 6) crResolve(6, 0, "SIX!");
        else { char b[12]; snprintf(b, sizeof b, crPend == 1 ? "1 RUN" : "%d RUNS", crPend); crResolve(crPend, 0, b); }
      }
    } break;
    case CRS_RES:
      if (crT >= 30) {
        if (crWin || crWk >= CR_WKTS || crBalls >= CR_BALLS) {
          crSt = CRS_OVER; endRun(CR_ID, crRuns, crHi); if (crWin && !newBest) fx(SFX_LEVEL, C_GOLD, 600);
        } else { if (crBalls % 6 == 0) toast("END OF OVER"); crDeliver(); }
      }
      break;
  }
}
static void crFigure(int x, int y, bool arm) {   // tiny person: head, body, optional raised arm
  u8g2.drawDisc(x, y - 3, 1); u8g2.drawBox(x - 1, y - 1, 3, 4); if (arm) u8g2.drawLine(x + 1, y - 1, x + 3, y - 5);
}
static void crDraw() {
  char b[16]; u8g2.setFont(FONT_S);
  // HUD: left = runs / wickets / overs, right = target / need
  u8g2.drawStr(2, 7, "RUNS"); u8g2.drawStr(2, 29, "WKT"); u8g2.drawStr(2, 49, "OVER");
  snprintf(b, sizeof b, "%u", crRuns); u8g2.setFont(FONT_M); u8g2.drawStr(2, 19, b);
  snprintf(b, sizeof b, "%u/%d", crWk, CR_WKTS); u8g2.setFont(FONT_S); u8g2.drawStr(2, 38, b);
  snprintf(b, sizeof b, "%u.%u", crBalls / 6, crBalls % 6); u8g2.setFont(FONT_M); u8g2.drawStr(2, 58, b);
  u8g2.setFont(FONT_S); u8g2.drawStr(94, 7, "TARGET"); u8g2.drawStr(94, 29, "NEED");
  snprintf(b, sizeof b, "%u", crTgt); u8g2.setFont(FONT_M); u8g2.drawStr(94, 19, b);
  snprintf(b, sizeof b, "%d", crTgt > crRuns ? crTgt - crRuns : 0); u8g2.drawStr(94, 40, b);
  u8g2.setFont(FONT_S);
  if (crSt <= CRS_BALL) u8g2.drawStr(94, 56, crKind == 0 ? "SLOW" : (crKind == 1 ? "MED" : "FAST"));
  for (uint8_t i = 0; i < crSN; i++) { char c[2] = {crStrip[i], 0}; u8g2.drawStr(94 + i * 6, 63, c); }
  // ground, pitch, stumps, fielders
  u8g2.drawCircle(64, 36, 27); u8g2.drawFrame(58, 13, 13, 46); u8g2.drawHLine(58, 18, 13); u8g2.drawHLine(58, 50, 13);
  for (uint8_t i = 0; i < 6; i++) u8g2.drawBox(crFld[i][0], crFld[i][1], 2, 2);
  u8g2.drawPixel(56, CR_HITY); u8g2.drawPixel(72, CR_HITY);               // timing marks
  for (int8_t i = -1; i <= 1; i++) {
    u8g2.drawVLine(64 + i * 2, 14, 3);
    if (crOutK == 2 && crSt == CRS_RES) u8g2.drawVLine(64 + i * 2 + i * (crT / 3), 54 - crT / 6, 3);   // stumps scatter
    else u8g2.drawVLine(64 + i * 2, 54, 4);
  }
  u8g2.drawBox(63, 61, 3, 2);                                               // keeper
  // bowler: run-up then arm swing
  int by = 8 + (crSt == CRS_RUN ? crT / 4 : 6); crFigure(64, by + 4, crSt == CRS_RUN ? (crT & 4) : crSt == CRS_BALL && crBy < 24);
  // batter + bat (idle tip -> shot tip)
  crFigure(54, 50, false);
  int tx = 59, ty = 57;
  if (crSwF >= 0) {
    int fx1 = crSwDir < 0 ? 51 : (crSwDir > 0 ? 71 : 64), fy1 = crLoft ? 40 : (crSwDir ? 49 : 43); int f = crSwF > 4 ? 4 : crSwF;
    tx = 59 + (fx1 - 59) * f / 4; ty = 57 + (fy1 - 57) * f / 4;
  }
  u8g2.drawLine(57, 50, tx, ty); u8g2.drawLine(58, 51, tx + 1, ty);
  // ball
  if (crSt == CRS_BALL) {
    int bx = 64 + crSx + (crLine * 3 - crSx) * (int)(crBy - 17) / (CR_STMY - 17); int bs = crBy > 40 ? 3 : 2;
    u8g2.drawBox(bx, (int)crBy, bs, bs);
    if (crBy > 30) u8g2.drawPixel(bx, (int)crBy - 3);
  } else if (crSt == CRS_FLY) {
    int bs = (crPend == 6 && crFl > 3 && crFl < 24) ? 3 : 2; u8g2.drawBox((int)crFx, (int)crFy, bs, bs);
  }
  if (crSt == CRS_OVER) {
    u8g2.setDrawColor(0); u8g2.drawBox(10, 8, 108, 48); u8g2.setDrawColor(1); u8g2.drawFrame(10, 8, 108, 48);
    u8g2.setFont(FONT_M); textC(crWin ? "YOU WIN!" : "INNINGS OVER", 20); u8g2.setFont(FONT_S);
    snprintf(b, sizeof b, "%u/%u", crRuns, crWk); char l[40]; snprintf(l, sizeof l, "SCORE %s  TARGET %u", b, crTgt); textC(l, 30);
    snprintf(l, sizeof l, "BEST %u", crHi); if (newBest && ((millis() / 300) & 1)) textC("* NEW BEST! *", 39); else textC(l, 39);
    textC("A:again   B:menu", 51);
  }
}
static void crIcon(int x, int y) {
  for (int i = -1; i <= 1; i++) u8g2.drawLine(x + 6 + i, y + 29, x + 19 + i, y + 11);   // bat blade
  u8g2.drawLine(x + 19, y + 11, x + 24, y + 3); u8g2.drawLine(x + 20, y + 11, x + 25, y + 4);   // handle
  u8g2.drawDisc(x + 24, y + 24, 4); u8g2.setDrawColor(0); u8g2.drawPixel(x + 23, y + 22); u8g2.drawPixel(x + 24, y + 24); u8g2.drawPixel(x + 25, y + 26); u8g2.setDrawColor(1);
}

#pragma once
// Dino Run - Chrome style: A/Up = jump, B/Down = duck (fast-fall in the air). Birds, clusters, day/night.
#define DN_ID  0
#define DN_GND 56

struct DnO { float x; uint8_t w, h, y, t; bool on; };   // t: 0 cactus, 1 bird. y = height above ground
static DnO dO[4];
static float dY, dVy, dSp, dDist, dNext, dCx[3];
static bool dDead, dDuck, dNight;
static uint16_t dScore, dHi;
static uint8_t dFr, dCy[3];
static uint32_t dBlink;

static void dnInit() {
  dY = DN_GND - 14; dVy = 0; dSp = 3.0f; dDist = 0; dNext = 60; dScore = 0;
  dDead = false; dDuck = false; dNight = false; dFr = 0; dBlink = 0; dHi = hiGet(DN_ID);
  for (uint8_t i = 0; i < 4; i++) dO[i].on = false;
  for (uint8_t i = 0; i < 3; i++) { dCx[i] = 20 + i * 45; dCy[i] = 14 + (i * 7) % 18; }
}

static void dnSpawn() {
  for (uint8_t i = 0; i < 4; i++) {
    if (dO[i].on) continue;
    DnO &o = dO[i]; o.on = true; o.x = 128;
    if (dScore >= 120 && random(100) < 30) {
      static const uint8_t by[3] = {2, 10, 22};          // low = jump, mid = duck/jump, high = stay low
      o.t = 1; o.w = 12; o.h = 8; o.y = by[random(3)];
      dNext = dSp * 16 + random(0, (long)(dSp * 12)) + 20;
    } else {
      static const uint8_t cw[4] = {5, 7, 13, 19}, ch[4] = {10, 15, 10, 10};
      uint8_t v = random(4); o.t = 0; o.w = cw[v]; o.h = ch[v]; o.y = 0;
      dNext = dSp * 14 + random(0, (long)(dSp * 14));
    }
    return;
  }
}

static void dnUpdate() {
  if (dDead) { if (overKeys()) dnInit(); return; }
  bool onG = dY >= DN_GND - 14;
  bool jump = in.a || in.dy < 0, down = in.b || in.dy > 0;
  if (onG && jump) { dVy = -5.8f; sfx(SFX_JUMP); }
  bool wasDuck = dDuck;
  dDuck = onG && down && !jump;
  if (dDuck && !wasDuck) sfx(SFX_DUCK);
  dVy += (!onG && down) ? 1.5f : 0.6f;
  dY += dVy;
  if (dY >= DN_GND - 14) { dY = DN_GND - 14; dVy = 0; }

  dSp = 3.0f + dScore * 0.0045f; if (dSp > 7.5f) dSp = 7.5f;
  dDist += dSp;
  uint16_t ns = (uint16_t)(dDist / 8);
  if (ns / 100 > dScore / 100) { fx(SFX_COIN, C_CYAN, 150); dBlink = millis() + 700; }
  dScore = ns; dNight = (dScore / 400) & 1; dFr++;
  for (uint8_t i = 0; i < 3; i++) { dCx[i] -= dSp * 0.25f; if (dCx[i] < -14) { dCx[i] = 128 + random(30); dCy[i] = 12 + random(20); } }

  float right = -1000;
  for (uint8_t i = 0; i < 4; i++) {
    if (!dO[i].on) continue;
    dO[i].x -= dSp;
    if (dO[i].x + dO[i].w < 0) dO[i].on = false;
    else if (dO[i].x + dO[i].w > right) right = dO[i].x + dO[i].w;
  }
  if (right < 128 - dNext) dnSpawn();

  float hx = 13, hw = 8, hy = dY + 2, hh = 12;
  if (dDuck) { hx = 11; hw = 14; hy = DN_GND - 7; hh = 7; }
  for (uint8_t i = 0; i < 4; i++) {
    if (!dO[i].on) continue;
    float oy = DN_GND - dO[i].y - dO[i].h;
    if (hitBox(hx, hy, hw, hh, dO[i].x + 1, oy + 1, dO[i].w - 2, dO[i].h - 1)) { dDead = true; endRun(DN_ID, dScore, dHi); break; }
  }
}

static void dnDino(int x, int y, bool duck, bool dead, bool legs) {
  if (!duck) {
    u8g2.drawBox(x + 7, y, 7, 6); u8g2.drawBox(x + 3, y + 5, 8, 6); u8g2.drawBox(x, y + 6, 4, 3); u8g2.drawBox(x + 11, y + 8, 2, 1);
    u8g2.setDrawColor(0); u8g2.drawPixel(x + 11, y + 1); if (dead) u8g2.drawPixel(x + 12, y + 2); u8g2.setDrawColor(1);
    u8g2.drawBox(x + 3, y + 11, 2, 3);
    if (legs) u8g2.drawBox(x + 7, y + 11, 2, 3); else u8g2.drawBox(x + 7, y + 10, 2, 2);
  } else {
    y = DN_GND - 8;
    u8g2.drawBox(x, y + 2, 12, 5); u8g2.drawBox(x + 10, y, 6, 5); u8g2.drawBox(x - 2, y + 3, 3, 2);
    u8g2.setDrawColor(0); u8g2.drawPixel(x + 13, y + 1); u8g2.setDrawColor(1);
    u8g2.drawBox(x + 2, y + 7, 2, 1); if (legs) u8g2.drawBox(x + 7, y + 7, 2, 1);
  }
}

static void dnDraw() {
  for (uint8_t i = 0; i < 3; i++) { int cx = (int)dCx[i], cy = dCy[i]; u8g2.drawBox(cx, cy, 10, 2); u8g2.drawBox(cx + 2, cy - 1, 6, 1); }
  if (dNight) { u8g2.drawDisc(100, 18, 4); u8g2.setDrawColor(0); u8g2.drawDisc(102, 17, 3); u8g2.setDrawColor(1); }
  u8g2.drawHLine(0, DN_GND, 128);
  for (int i = 0; i < 6; i++) { int x = ((i * 29) - (int)dDist) % 128; if (x < 0) x += 128; u8g2.drawPixel(x, DN_GND + 3 + (i & 1) * 3); }
  bool air = dY < DN_GND - 14;
  dnDino(12, (int)dY, dDuck, dDead, air || ((dFr / 4) & 1));
  for (uint8_t i = 0; i < 4; i++) {
    if (!dO[i].on) continue;
    int ox = (int)dO[i].x, w = dO[i].w, h = dO[i].h;
    if (dO[i].t == 0) {
      for (int k = 0; k + 3 <= w; k += 6) {
        int tx = ox + k + 1, th = ((k / 6) & 1) ? h - 3 : h;
